import { build } from "esbuild";
import { resolve } from "node:path";

const root = resolve(import.meta.dirname, "..");

// site-content.js is generated by embed-assets.mjs next to the bundle, so it stays an external import.
const siteContentExternal = {
  name: "site-content-external",
  setup(pluginBuild) {
    pluginBuild.onResolve({ filter: /(^|\/)site-content\.js$/ }, () => ({
      path: "./site-content.js",
      external: true,
    }));
  },
};

await build({
  entryPoints: [resolve(root, "worker/src/index.js")],
  outfile: resolve(root, "dist/server/index.js"),
  bundle: true,
  format: "esm",
  platform: "neutral",
  target: "es2022",
  plugins: [siteContentExternal],
  logLevel: "warning",
});
